<?php $pageTitle='Applications';require_once __DIR__.'/functions.php';$apps=db()->query("SELECT * FROM applications ORDER BY id DESC")->fetchAll();include 'includes/header.php';?><section class="page-head"><div class="container"><h1>Applications</h1><p class="muted">Software and student tools uploaded by the site administrator.</p></div></section><section class="section" style="padding-top:10px"><div class="container cards"><?php if(!$apps):?><div class="panel"><h3>No applications uploaded yet.</h3><p class="muted">Admin can add APK, EXE, MSI or ZIP packages.</p></div><?php endif;?><?php foreach($apps as $a):?><article class="card"><div class="thumb"><?=e($a['icon'])?></div><div class="card-body"><h3><?=e($a['title'])?></h3><p><?=e($a['description'])?></p><div class="meta"><span>Version <?=e($a['version'])?></span><span><?=number_format($a['size_bytes']/1048576,2)?> MB</span></div><a class="primary" style="margin-top:14px" href="<?=e($a['file_path'])?>" download>Download</a></div></article><?php endforeach;?></div></section><?php include 'includes/footer.php';?>
